mapper.select:
SELECT e.id AS id, e.tenant_id AS tenantId, e.objective_id AS objectiveId, e.assignment_id AS assignmentId, e.result_id AS resultId, e.evaluatee_id AS evaluateeId, e.evaluatee_name AS evaluateeName, e.evaluator_id AS evaluatorId, e.evaluator_name AS evaluatorName, e.evaluator_source AS evaluatorSource, e.weight AS weight, e.status AS status, e.invite_time AS inviteTime, e.remind_count AS remindCount, r.score AS responseScore, r.dimension_scores AS responseDimensions, r.comment_text AS responseComment, r.submit_time AS responseSubmitTime FROM hr_perf_evaluator e LEFT JOIN hr_perf_evaluator_response r ON r.evaluator_id = e.id AND r.deleted = 0 WHERE e.tenant_id = #{tenantId} AND e.deleted = 0 AND e.objective_id = #{objectiveId}
AND e.evaluatee_id = #{evaluateeId}
ORDER BY e.evaluatee_id, e.evaluator_source, e.id
